    specials = draw(st.lists(st.integers(-4, 4), min_size=n - 2, max_size=n - 2))
    total = sum(specials)
    # outlier drawn from a small range that includes extremes scaled down,
    # and sometimes equal to a special value or the sum (allowed by the statement)
    outlier = draw(st.one_of(
        st.integers(-6, 6),
        st.sampled_from([total, -total, 0, 1000, -1000]),
    ))
    items = specials + [total, outlier]
    arr = draw(st.permutations(items))
    return json.dumps(list(arr))

