import json
from hypothesis import strategies as st


@st.composite
def gen(draw):
    n = draw(st.integers(3, 7))
    k = n - 2
    specials = draw(st.lists(st.integers(-5, 5), min_size=k, max_size=k))
    s = sum(specials)
    outlier = draw(st.integers(-5, 5))
    arr = specials + [s, outlier]
    arr = draw(st.permutations(arr))
    return json.dumps(list(arr)) + "\n"


def validate(inp):
    lines = inp.split("\n")
    if len(lines) != 2 or lines[1] != "":
        return False
    try:
        nums = json.loads(lines[0])
    except Exception:
        return False
    if not isinstance(nums, list):
        return False
    n = len(nums)
    if not (3 <= n <= 10**5):
        return False
    if not all(type(x) is int and -1000 <= x <= 1000 for x in nums):
        return False
    # at least one potential outlier must exist
    for s in range(n):
        for o in range(n):
            if s == o:
                continue
            total = sum(nums[k] for k in range(n) if k != s and k != o)
            if total == nums[s]:
                return True
    return False


def ref(inp):
    nums = json.loads(inp.split("\n")[0])
    n = len(nums)
    best = None
    for s in range(n):
        for o in range(n):
            if s == o:
                continue
            total = 0
            for k in range(n):
                if k != s and k != o:
                    total += nums[k]
            if total == nums[s]:
                if best is None or nums[o] > best:
                    best = nums[o]
    return json.dumps(best)
